// Helper functions
function getCategoryColorClass(category: string) {
  const categories: Record<string, string> = {
    '인건비': 'text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full text-xs font-medium',
    '재료비': 'text-green-600 bg-green-50 px-2 py-0.5 rounded-full text-xs font-medium',
    // Other categories
  };

  return categories[category] || 'text-gray-600 bg-gray-50 px-2 py-0.5 rounded-full text-xs font-medium';
}

function getReceiptStatusClass(status: string) {
  const statuses: Record<string, string> = {
    '완료': 'text-success-600 bg-success-50 px-2 py-0.5 rounded-full text-xs font-medium',
    '대기': 'text-warning-600 bg-warning-50 px-2 py-0.5 rounded-full text-xs font-medium',
    '없음': 'text-gray-600 bg-gray-50 px-2 py-0.5 rounded-full text-xs font-medium',
  };

  return statuses[status] || 'text-gray-600 bg-gray-50 px-2 py-0.5 rounded-full text-xs font-medium';
}
```

